begin;
drop policy if exists deals_ops_write on public.deals;create policy deals_ops_insert on public.deals for insert to authenticated with check(has_org_role(organization_id,array['platform_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role]));create policy deals_ops_update on public.deals for update to authenticated using(has_org_role(organization_id,array['platform_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role])) with check(has_org_role(organization_id,array['platform_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role]));create policy deals_ops_delete on public.deals for delete to authenticated using(has_org_role(organization_id,array['platform_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role]));
drop policy if exists data_rooms_owner_write on public.data_rooms;create policy data_rooms_owner_insert on public.data_rooms for insert to authenticated with check(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]));create policy data_rooms_owner_update on public.data_rooms for update to authenticated using(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])) with check(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]));create policy data_rooms_owner_delete on public.data_rooms for delete to authenticated using(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]));
drop policy if exists data_room_members_manager_write on public.data_room_members;create policy data_room_members_manager_insert on public.data_room_members for insert to authenticated with check(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])));create policy data_room_members_manager_update on public.data_room_members for update to authenticated using(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]))) with check(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])));create policy data_room_members_manager_delete on public.data_room_members for delete to authenticated using(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])));
create index if not exists data_room_members_granted_by_idx on public.data_room_members(granted_by);create index if not exists data_room_members_organization_id_idx on public.data_room_members(organization_id);create index if not exists data_rooms_created_by_idx on public.data_rooms(created_by);create index if not exists document_versions_uploaded_by_idx on public.document_versions(uploaded_by);create index if not exists nda_acceptances_organization_id_idx on public.nda_acceptances(organization_id);create index if not exists nda_acceptances_user_id_idx on public.nda_acceptances(user_id);create index if not exists workflow_events_actor_id_idx on public.workflow_events(actor_id);
commit;